{
  "justification": "Europe overwhelmingly dominates issue salience (44%), while the electorate sits slightly right-of-centre overall (5.16/10) but more authoritarian on the derived social scale (6.56/10) and modestly pro-redistribution (4.56/10). This combination elevates authority and loyalty (Europe/immigration/terrorism/defence salience) while keeping care and equality prominent via health and redistribution, with proportionality moderate and sanctity low given minimal explicit moral/purity concerns.",
  "foundations": [
    {
      "foundation": "authority",
      "basis": "Derived authority–liberty mean 6.56 (authoritarian); Europe, terrorism, crime, and defence salience",
      "weight": 0.24
    },
    {
      "foundation": "loyalty",
      "basis": "High salience of Europe (44.4%), immigration (10.7%), defence (0.5%), and Scot-ind (0.5%)",
      "weight": 0.19
    },
    {
      "foundation": "equality",
      "basis": "Redistribution self-placement 4.56 (leans to redistribution); salience of inequality (1.1%) and austerity (1.1%)",
      "weight": 0.20
    },
    {
      "foundation": "care",
      "basis": "Health is the second-most salient issue (10.9%) plus poverty, welfare, social care, and living costs",
      "weight": 0.18
    },
    {
      "foundation": "proportionality",
      "basis": "Centre-right left–right mean (5.16) and economy-general/election outcome concerns",
      "weight": 0.13
    },
    {
      "foundation": "sanctity",
      "basis": "Very low explicit moral/purity salience (morals 0.2%, gender/sexuality 0.0%) with minor cues via immigration/terrorism",
      "weight": 0.06
    }
  ]
}
